#!/bin/bash
# Regenerate RSL implementation from specs
# This script regenerates all RSL generated code from the spec files.
#
# types_gen.rs is PARTIALLY generated:
#   - Struct/enum definitions + View impls are generated by the transpiler
#   - Helper functions (abstractify_*, validity predicates, ballot comparisons,
#     StaticParams, InitReplicaConstants, clone helpers, etc.) are appended manually
#   - CBallot/CRequest/CReply/CVote are NOT in types_gen.rs (they live in types_i.rs
#     because they need define_struct_and_derive_marshalable! macro)
#
# NOTE: Generated function files (*_gen.rs) have extensive hand-modifications
# from V3.6-V3.7 (clone fixes, iterator rewrites, assume() additions).
# Regenerating them will lose those fixes. Only regenerate individual files
# when you intend to re-apply those fixes afterward.

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
TRANSPILER_DIR="$PROJECT_ROOT/transpiler"

echo "=== RSL Code Regeneration ==="
echo "Project root: $PROJECT_ROOT"

# Build the transpiler if needed
echo ""
echo "Building transpiler..."
cd "$TRANSPILER_DIR"
cargo build --release

TRANSPILER="$TRANSPILER_DIR/target/release/verus-transpile"

# Generate types_gen.rs (struct definitions only — helpers must be appended manually)
echo ""
echo "Generating types_gen.rs struct definitions..."
echo "  NOTE: This generates ONLY struct/enum definitions + View impls."
echo "  Helper functions (abstractify_*, validity predicates, etc.) must be"
echo "  appended manually after generation."
$TRANSPILER generate-types \
    -i "$PROJECT_ROOT/src/protocol/RSL/types.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/parameters.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/configuration.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/constants.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/acceptor.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/learner.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/election.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/executor.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/proposer.rs" \
    -i "$PROJECT_ROOT/src/protocol/RSL/replica.rs" \
    -c "$PROJECT_ROOT/src/protocol/RSL/types_transpile.toml" \
    -o "$PROJECT_ROOT/src/generated/RSL/types_gen.rs"

echo "  Generated. Remember to manually append helper functions!"

# Regenerate all RSL module functions
# WARNING: This will overwrite hand-modifications from V3.6-V3.7!
for module in acceptor learner executor proposer replica broadcast election; do
    echo ""
    echo "Regenerating $module functions..."
    $TRANSPILER \
        --input "$PROJECT_ROOT/src/protocol/RSL/${module}.rs" \
        --annotations "$PROJECT_ROOT/src/protocol/RSL/${module}.automan" \
        --config "$PROJECT_ROOT/src/protocol/RSL/transpile.toml" \
        --output "$PROJECT_ROOT/src/generated/RSL/${module}_gen.rs"
done

# Format generated code for consistency
echo ""
echo "Formatting generated code..."
cd "$PROJECT_ROOT"
cargo fmt -- src/generated/RSL/*.rs

echo ""
echo "=== Regeneration complete ==="
echo ""
echo "Generated files:"
ls -la "$PROJECT_ROOT/src/generated/RSL/"
